// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 fuzzChangeFee, address fuzzBaseToken, address fuzzNft, uint128 fuzzVBase, uint128 fuzzVNft, uint16 fuzzFeeRate, bytes32 fuzzMerkleRoot, bool fuzzUseOracle, bool fuzzPayRoyalties) public {
        if (fuzzFeeRate > 6000) fuzzFeeRate = uint16(fuzzFeeRate % 6001);
        bool ok;
        try c.initialize(fuzzBaseToken, fuzzNft, fuzzVBase, fuzzVNft, fuzzChangeFee, fuzzFeeRate, fuzzMerkleRoot, fuzzUseOracle, fuzzPayRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.changeFee() == fuzzChangeFee);
        } else {
            assertTrue(c.initialized() == false);
        }
    }
}
